import csv, pathlib, collections
rows=[r for r in csv.DictReader(open('A1/in/part-5.tsv'),delimiter='\t') if r['machine']=='ubuntu' and r['kind'] in ('stored','stored-directory-skeleton')]
out=pathlib.Path('A1/c1/part-5.1.tsv')
header=['id','decision','sentences','what_it_does','basis','reason']
seen={r['id'] for r in csv.DictReader(out.open(),delimiter='\t')} if out.exists() else set()
f=out.open('a'); w=csv.writer(f,delimiter='\t',lineterminator='\n')
if not out.stat().st_size:w.writerow(header)
def add(i,d,s,what,reason,doc=None):
 if rows[i]['id'] in seen:return
 assert len(what.split())<=15,(i,what)
 assert len(reason.split())<=30,(i,reason)
 w.writerow([rows[i]['id'],d,s,what,'doc:'+doc if doc else 'evidence',reason]); f.flush();seen.add(rows[i]['id'])
